-- 2145 requirements of WotLK and Cata criteria the client data does not carry
CREATE TABLE IF NOT EXISTS `achievement_criteria_requirement` (
  `criteria_id` int unsigned NOT NULL DEFAULT '0',
  `min_build` int unsigned NOT NULL DEFAULT '0',
  `max_build` int unsigned NOT NULL DEFAULT '0',
  `requirement` tinyint unsigned NOT NULL DEFAULT '0',
  `param1` int unsigned NOT NULL DEFAULT '0',
  `param2` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`criteria_id`,`min_build`,`requirement`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


